// Evidence-backed request-path tests for the AI Videos leaf (Phase 3.1).
//
// Generated by scripts/research/gen-31-tests.py from the rows in api.md, which in turn come from
// docs/research/apk-endpoints.md. Each test calls the method and inspects the URL that actually
// reaches `fetch`, so a rename or a route regression fails here rather than in production.

import BandlabSDK from 'bandlabx';

function makeClient(): BandlabSDK {
  return new BandlabSDK({ bearerToken: 'My Bearer Token', baseURL: 'http://127.0.0.1:4010' });
}

/** Run `fn`, capture the URL of the first request, and answer it with a stub response. */
async function captureURL(fn: (c: BandlabSDK) => Promise<unknown>): Promise<string> {
  const calls: string[] = [];
  const realFetch = globalThis.fetch;
  globalThis.fetch = (async (input: any) => {
    calls.push(typeof input === 'string' ? input : input?.url ?? String(input));
    return new Response('{}', { status: 200, headers: { 'content-type': 'application/json' } });
  }) as typeof fetch;
  try {
    await fn(makeClient()).catch(() => undefined);
  } finally {
    globalThis.fetch = realFetch;
  }
  if (!calls.length) throw new Error('no request was issued');
  return calls[0]!;
}

describe('AI Videos paths match the APK evidence', () => {
  test('GET /ai-videos/ai-tokens/price hits /ai-videos/ai-tokens/price', async () => {
    const url = await captureURL((c) => c.aiVideos.retrieveTokenPrice());
    expect(url).toContain('/ai-videos/ai-tokens/price');
  });

  test('POST /ai-videos/generate hits /ai-videos/generate', async () => {
    const url = await captureURL((c) => c.aiVideos.generate({}));
    expect(url).toContain('/ai-videos/generate');
  });

  test('GET /ai-videos/jobs hits /ai-videos/jobs', async () => {
    const url = await captureURL((c) => c.aiVideos.listJobs({}));
    expect(url).toContain('/ai-videos/jobs');
  });

  test('GET /ai-videos/styles hits /ai-videos/styles', async () => {
    const url = await captureURL((c) => c.aiVideos.listStyles({}));
    expect(url).toContain('/ai-videos/styles');
  });

  test('GET /ai-videos/updates hits /ai-videos/updates', async () => {
    const url = await captureURL((c) => c.aiVideos.listUpdates({}));
    expect(url).toContain('/ai-videos/updates');
  });
});
